////////////////////////////////////////////////////////////////////////////////
#define pi acos(-1.)
#define deg pi/180.
#define time iTime*pi/10.
#define R iResolution.xy
#define ar R.x/R.y
vec3 cs = vec3(1.,2.,3.);
mat2 r2d(float a) {
    return mat2(cos(a),sin(a),-sin(a),cos(a));
}
// box-filted cos(x)
vec3 fcos( in vec3 x )
{
    vec3 w = fwidth(x);
    #if 1
    return cos(x) * sin(0.5*w)/(0.5*w);       // exact
    #else
    return cos(x) * smoothstep(6.2832,0.0,w); // approx
    #endif    
}
vec3 t1(vec2 uv, float t, float v) {
    vec3 col = vec3(0.);
    float c = length(uv);

    uv = vec2(log(length(uv)),atan(uv.x,uv.y));
    //uv.x *= sin(time*0.1);
    //uv.x += time*8.;
    //uv.x *= sin(-time*0.1)*0.1+0.5;
    //uv.x -= t*-0.2+time*0.1;
    uv.x += v*-2.;
    uv.x *= 0.3;
    //uv.x += time10.5;
    //uv.y += -time*10.;
    uv.x += uv.y*0.0795;
    float sx = floor(uv.x*2.)/pi+2.+fract((uv.y/pi/2.+0.5))*-0.3183;
    //uv.x += sin(uv.y*80.)*0.1;
    uv.x = (fract(uv.x*2.)-0.5)/2.;
    //
    //uv.x *= 0.5;

    float s = (min(abs(uv.x-sin(uv.y*8.)*0.1),abs(uv.x+sin(uv.y*8.)*0.1)));
    //s = min(s,abs(-abs(uv.x)+0.1));
    //s = min(s,abs(-abs(uv.x)+0.2));
    //s = min(s,(min(abs((abs(uv.x)-0.15)-sin(uv.y*8.)*0.05),abs((abs(uv.x)-0.15)+cos(uv.y*8.)*0.05))));
    //s += 0.1;
    col -= (smoothstep(0.01,0.,abs(uv.x-0.25))+smoothstep(0.01,0.,abs(uv.x+0.25)))*0.02;
    col -= fcos(uv.xxx*190.+t*25.)*0.1;

    //col += sin(sx*2.);
    col += fcos(sx*28.+t+cs*0.2+t*8.)*0.12;
    col += fcos(sx*0.65*v*v+t*0.1+cs*0.8+time*2.)*0.4+0.6;
    //col += sin(cs+s*200.+sx*10.+t*10.)*0.5;
    //col += smoothstep(0.002+pow((1-c),5.)*0.02,0.,s)*(c*0.5+0.5);
    col = clamp(col,-0.,1.);
    return col;
}

vec3 t2(vec2 uv, float t) {
    vec3 col = vec3(0.);
    float c = length(uv);
    uv = uv/dot(uv,uv);
    uv *= 0.002;
    uv *= 30.;
    //uv.xy *= pow(time*0.3,2.)+1.;
    uv = (fract(uv*12.-0.5)-0.5)/12.;
    uv = abs(uv)-0.024;
    uv *= r2d(time*-12.);
    col = t1(uv,t,log(c)*0.8)*0.7;
    col = clamp(col,0.,1.);
    col = mix(col,vec3(0.5),log(1.-c)*0.);
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 tv = uv;
    uv -= 0.5;
    uv.x *= ar;
    uv *= 0.6;
    vec3 col = vec3(0.);
    float c = length(uv);
    for (int j=0;j<4;j++) {
    float jj = float(j+1);
    vec2 ov = uv;
    uv *= 1.+sin(time+jj+c+sin(uv.x*8.-time)+sin(uv.y*8.+time))*0.06;
    uv *= r2d(sin(time+jj+c*2.)*deg*4.);
    //uv = abs(uv)-0.25;
    for (int i=0;i<12;i++) {
        float ii = float(i);
        float aa = fract(ii/48.+jj/3.+time+c*1.5);
        float sa = abs(aa-0.5)*2.;
        uv *= 1.+sin(time+jj+c+cos(uv.x*8.-time)+cos(uv.y*8.+time))*0.0005;
        vec3 nl = t2(uv,time-ii*pi)*sa*0.03*(sin(jj*pi+time)*0.5+0.5);
        //col += (sin(nl*12.+atan(uv.x,uv.y)+time));
        col += nl+sin(col*8.+nl*12.+sin(atan(uv.x,uv.y))+time+c*2.)*0.002;
        //col += floor(nl*128.)/68.;
        uv += vec2(sin(time+c*5.*sa+sa+cos(uv.x*18.+time)+jj),cos(time+c*8.*sa+sa+sin(uv.y*18.+time*0.4)))*0.0013*sa*sin(c*1.2+time+jj*2.)*jj;

    }
    ov *= 0.95;
    uv = ov;
    }
    //col -= 0.12;
    col *= 3.;
    col += 0.2;
    //col = sin(col*12.+time+atan(uv.x,uv.y)+c*8.)*0.5+0.5;
   // col -= 0.44;
   // col *= 4.9;
    col = pow(col,vec3(2./1.2));
    //col -= sin(col*8.+time)*0.5+0.5;
    // (sin(col+time)*0.75+0.25)+sin(col-1.2)*0.;

    //col = sin(cs+col*8.+time)*0.5+0.5;

    fragColor = vec4(col,1.0);
}
